query_definitions.source:
query "mysql_ssl_enabled" {
  sql = <<-EOQ
    select
      s.id as resource,
      case
        when ssl_enforcement = 'Disabled' then 'alarm'
        else 'ok'
      end as status,
      case
        when ssl_enforcement = 'Disabled' then s.name || ' SSL connection disabled.'
        else s.name || ' SSL connection enabled.'
      end as reason
      ${replace(local.tag_dimensions_qualifier_sql, "__QUALIFIER__", "s.")}
      ${replace(local.common_dimensions_qualifier_sql, "__QUALIFIER__", "s.")}
      ${replace(local.common_dimensions_qualifier_subscription_sql, "__QUALIFIER__", "sub.")}
    from
      azure_mysql_server as s
      left join azure_subscription as sub on sub.subscription_id = s.subscription_id;
  EOQ
}

