query_definitions.source:
query "keyvault_firewall_enabled" {
  sql = <<-EOQ
    select
      kv.id as resource,
      case
        when jsonb_array_length(network_acls -> 'ipRules') > 0 then 'ok'
        else 'alarm'
      end as status,
      case
        when jsonb_array_length(network_acls -> 'ipRules') > 0 then name || ' firewall enabled.'
        else name || ' firewall disabled.'
      end as reason
      ${replace(local.tag_dimensions_qualifier_sql, "__QUALIFIER__", "kv.")}
      ${replace(local.common_dimensions_qualifier_sql, "__QUALIFIER__", "kv.")}
      ${replace(local.common_dimensions_qualifier_subscription_sql, "__QUALIFIER__", "sub.")}
    from
      azure_key_vault kv
      left join azure_subscription as sub on sub.subscription_id = kv.subscription_id;
  EOQ
}

